{
  "name": "@bwanamaker/brandobot",
  "version": "0.4.0",
  "description": "Browser automation for OpenCode and Pi through Playwright CLI.",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bwanamaker/brandobot.git"
  },
  "bugs": "https://github.com/bwanamaker/brandobot/issues",
  "homepage": "https://github.com/bwanamaker/brandobot#readme",
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./pi": {
      "types": "./dist/pi.d.ts",
      "default": "./dist/pi.js"
    }
  },
  "pi": {
    "extensions": ["./dist/pi.js"]
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "lint": "eslint .",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "bun test && npm run test:pi",
    "test:pi": "npm run build && node --test test/pi-node.mjs",
    "prepack": "npm run build"
  },
  "engines": {
    "node": "^22.22.2 || ^24.15.0 || >=26.0.0",
    "opencode": ">=1.18.25"
  },
  "keywords": [
    "opencode",
    "pi-package",
    "plugin",
    "playwright",
    "browser-automation"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.25",
    "@playwright/cli": "0.1.18",
    "@playwright/test": "1.63.0-alpha-2026-08-05"
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "^0.87.1",
    "@eslint/js": "^10.0.1",
    "bun-types": "^1.3.9",
    "eslint": "^10.10.0",
    "globals": "^17.12.0",
    "typebox": "^1.3.27",
    "typescript": "^5.9.3",
    "typescript-eslint": "^8.70.0"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": { "optional": true },
    "typebox": { "optional": true }
  }
}

export { default } from "./opencode.js";
export * from "./opencode.js";
//# sourceMappingURL=index.js.map
